--
-- Стенд Placitum: дерево, с которого живёт deploy/docker-compose.yml.
--
-- Это не поставка и не пример в документации: те же серверы, пути, апстримы и
-- списки, что раньше приезжали сидами 011, 017, 018, 024, 041, 042, 045, 051,
-- 070, 072 и 074. Клиенту они не едут -- initdb.d читает только верхний уровень
-- controller/schema, а этот файл лежит в подкаталоге.
--
-- Кто катает: предполёт e2e (tests/lib/bootstrap.mjs) после пересоздания тома.
-- Руками -- psql -f /docker-entrypoint-initdb.d/stand/stand.sql изнутри
-- контейнера postgres.
--
-- Идемпотентен: вставки с on conflict do nothing, правки -- по имени. Ложится
-- поверх 02-shipped.sql, отдельно от него не применяется.
--

-- граф объявлений http {}: чем стенд отличается от пустой поставки
update public.http_spaces set waf = '{"inspectors": {"ip": {"needs": "none", "timeoutMs": 20}, "vlai": {"after": ["ip", "modsec"], "needs": "headers,args,body", "timeoutMs": 200}, "ip-ext": {"needs": "none", "profile": "ext", "timeoutMs": 20}, "modsec": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "timeoutMs": 500}, "ip-admin": {"needs": "none", "profile": "admin", "timeoutMs": 20}, "ip-heavy": {"needs": "none", "profile": "heavy", "timeoutMs": 20}, "ip-unknown": {"needs": "none", "profile": "no-such", "timeoutMs": 20}, "modsec-api": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "api", "timeoutMs": 500}, "modsec-e2e": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "e2e", "timeoutMs": 500}, "modsec-deny": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "deny", "timeoutMs": 500}, "modsec-allow": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "allow", "timeoutMs": 500}, "modsec-strict": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "strict", "timeoutMs": 500}, "modsec-unknown": {"body": "full", "after": ["ip"], "needs": "headers,args,body", "profile": "no-such-profile", "timeoutMs": 500}}}'::jsonb
  where name = 'default';

-- профили default, переписанные стендом под демонстрацию
update public.auth_profiles set doc = '{"mode":"off"}'::jsonb
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.captcha_profiles set doc = '{"mode":"enforce","page":"95da0716-6811-487e-bacd-58678b8ece75","path":"/waf/captcha","trigger":{"when":"score","prior":[{"reasons":["WANT_CAPTCHA"],"scoreAt":0,"inspector":"*"}],"scoreAt":60,"reverifyAt":90,"reverifyAfterS":600}}'::jsonb, description = 'Виджет по счёту и по просьбе соседей'
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.json_profiles set doc = '{"mode":"off","description":"Контракт не задан: проверка выключена"}'::jsonb, description = 'Контракт не задан: проверка выключена'
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.counter_profiles set doc = '{"mode":"enforce","request":{"judge":[],"enabled":true},"response":{"enabled":true,"measure":[]},"description":"Правил нет: счётчик молчит"}'::jsonb, description = 'Правил нет: счётчик молчит'
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.action_profiles set doc = '{"mode":"enforce","rules":[],"description":"Правил нет: инспектор молчит"}'::jsonb, description = 'Правил нет: инспектор молчит'
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.rewrite_profiles set doc = '{"mode":"off"}'::jsonb
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.vlai_profiles set doc = '{"mode":"off"}'::jsonb
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');
update public.ip_profiles set description = 'office + bot-a'
  where name = 'default' and http_space_id = (select id from public.http_spaces where name = 'default');

